<script setup>
import { computed, ref } from 'vue'
import { ArrowRight, CalendarDays, Check, ChevronDown as ChevronDownIcon, CreditCard, Download, MoreHorizontal, Plus, ReceiptText, Search, WalletCards } from 'lucide-vue-next'
import { confirmPayment, store } from '../demo-store'

const tab = ref('payments')
const query = ref('')
const filteredPayments = computed(() => store.payments.filter((payment) => `${payment.id} ${payment.student} ${payment.channel}`.toLowerCase().includes(query.value.toLowerCase())))
function statusClass(value) { return value === 'Terbayar' ? 'status-terbit' : value === 'Menunggu' ? 'status-review' : 'status-arsip' }
</script>

<template>
  <div class="view-wrap">
    <div class="page-title-row"><div><div class="eyebrow">PENDAPATAN <span>/</span> FINANCE</div><h1>Langganan & pembayaran</h1><p class="page-subtitle">Kelola paket akses, transaksi, refund, dan status hak akses murid.</p></div><button class="button button-primary" v-if="tab === 'plans'"><Plus :size="17" /> Buat paket langganan</button><button class="button button-outline" v-else><Download :size="16" /> Ekspor transaksi</button></div>
    <div class="finance-metrics"><div class="finance-metric"><span class="metric-icon green"><WalletCards :size="18" /></span><div><small>Penerimaan terkonfirmasi</small><strong>Rp 38.420.000</strong><em><span class="trend-up">+12,4%</span> bulan ini</em></div></div><div class="finance-metric"><span class="metric-icon lilac"><CreditCard :size="18" /></span><div><small>Langganan aktif</small><strong>1.847</strong><em>pada 3 paket aktif</em></div></div><div class="finance-metric"><span class="metric-icon peach"><ReceiptText :size="18" /></span><div><small>Perlu konfirmasi</small><strong>3 transaksi</strong><em>Menunggu pembayaran</em></div></div></div>
    <div class="content-tabs"><button :class="['content-tab', { active: tab === 'payments' }]" @click="tab = 'payments'">Pembayaran <span>{{ store.payments.length }}</span></button><button :class="['content-tab', { active: tab === 'plans' }]" @click="tab = 'plans'">Paket langganan <span>{{ store.plans.length }}</span></button></div>
    <template v-if="tab === 'payments'"><div class="filter-row"><label class="search-field"><Search :size="17" /><input v-model="query" placeholder="Cari invoice atau nama murid..." /><kbd>⌘ K</kbd></label><button class="filter-select"><CalendarDays :size="15" /> 30 hari terakhir <ChevronDownIcon /></button><button class="filter-select">Semua status <ChevronDownIcon /></button></div><section class="panel table-panel"><div class="table-scroll"><table class="data-table payment-table"><thead><tr><th>INVOICE</th><th>MURID / PAKET</th><th>METODE</th><th>TANGGAL</th><th>JUMLAH</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="payment in filteredPayments" :key="payment.id"><td><b class="invoice-id">{{ payment.id }}</b></td><td><div class="table-primary"><b>{{ payment.student }}</b><small>{{ payment.plan }}</small></div></td><td><span class="payment-channel"><CreditCard :size="15" />{{ payment.channel }}</span></td><td class="muted-cell">{{ payment.date }}</td><td class="amount-cell">{{ payment.amount }}</td><td><span :class="['status-tag', statusClass(payment.status)]"><i></i>{{ payment.status }}</span></td><td><button v-if="payment.status === 'Menunggu'" class="inline-action" @click="confirmPayment(payment)"><Check :size="14" /> Konfirmasi</button><button v-else class="icon-button tiny"><MoreHorizontal :size="16" /></button></td></tr></tbody></table></div><div class="table-footer"><span>Menampilkan {{ filteredPayments.length }} transaksi contoh</span><div class="pagination"><button disabled>‹</button><button class="current-page">1</button><button>2</button><button>›</button></div></div></section><div class="info-callout"><div class="callout-mark">i</div><p><b>Hak akses hanya aktif setelah pembayaran dikonfirmasi.</b> Produksi akan memakai callback Midtrans terverifikasi dan idempoten. Demo ini tidak terhubung ke gateway.</p><button class="text-button">Lihat log audit <ArrowRight :size="14" /></button></div></template>
    <template v-else><div class="plan-grid"><article v-for="(plan, index) in store.plans" :key="plan.name" class="panel plan-card"><div class="plan-top"><span :class="['plan-icon', `plan-${index}`]"><WalletCards :size="19" /></span><span class="status-tag status-terbit"><i></i>{{ plan.state }}</span></div><h2>{{ plan.name }}</h2><p>{{ plan.validity }} akses · {{ plan.quota }}</p><strong>{{ plan.price }}</strong><div class="plan-bottom"><span>{{ plan.students }} murid berlangganan</span><button class="icon-button tiny"><MoreHorizontal :size="16" /></button></div></article><button class="add-plan-card"><span><Plus :size="20" /></span><b>Tambah paket</b><small>Atur masa aktif dan kuota baru</small></button></div><div class="info-callout"><div class="callout-mark">i</div><p>Perpanjangan dilakukan manual. Pembatalan mempertahankan akses sampai masa bayar berakhir; refund penuh mencabut akses. Refund parsial tidak tersedia pada MVP.</p></div></template>
  </div>
</template>
